    ag_output.mode = AG_FAULT;
    ag_output.good = ag_state.good;
    ag_output.angle_rad = 0.0;
    ag_output.rate_norm_rad_s = 0.0;
    ag_output.rate_energy = 0.0;
    return;
}

/* relative rotation: q_err = conj(cur) * tgt */
conj_q = adcs_quat_conjugate(&cur_q);
rel_q = adcs_quat_multiply(&conj_q, &tgt_q);
idq = (adcs_quat_t){1.0, 0.0, 0.0, 0.0};
{
    double ad = adcs_quat_abs_dot(&rel_q, &idq);
    if (ad > 1.0)
        ad = 1.0;
    angle = 2.0 * acos(ad);
}

if (!isfinite(angle)) {
    ag_state.mode = AG_FAULT;
    ag_output.mode = AG_FAULT;
    ag_output.good = ag_state.good;
    ag_output.angle_rad = 0.0;
    ag_output.rate_norm_rad_s = 0.0;
    ag_output.rate_energy = 0.0;
    return;
}

rate_norm = adcs_vec3_norm(ag_input.rate_rad_s);
rate_energy = adcs_vec3_dot(ag_input.rate_rad_s, ag_input.rate_rad_s);

if (!isfinite(rate_norm) || !isfinite(rate_energy)) {
    ag_state.mode = AG_FAULT;
    ag_output.mode = AG_FAULT;
    ag_output.good = ag_state.good;
    ag_output.angle_rad = 0.0;
    ag_output.rate_norm_rad_s = 0.0;
    ag_output.rate_energy = 0.0;
    return;
}

/* decision table */
if (ag_input.enable == 0) {
    ag_state.mode = AG_SLEW;
    ag_state.good = 0U;
} else if ((angle <= ag_config.angle_limit_rad) && (rate_norm <= ag_config.rate_limit_rad_s)) {
    ag_state.good = ag_state.good + 1U;
    if (ag_state.good >= ag_config.required) {
        ag_state.mode = AG_SETTLED;
    }
} else {
    ag_state.mode = AG_SLEW;
    ag_state.good = 0U;
}

ag_output.mode = ag_state.mode;
ag_output.good = ag_state.good;
ag_output.angle_rad = angle;
ag_output.rate_norm_rad_s = rate_norm;
ag_output.rate_energy = rate_energy;

